			return refuse(Error, textPreviousGone(s.Previous))
		}
		return switchTo(s.Previous, s)
	}
	if !validName(arg) {
		return refuse(Error, textInvalid(arg))
	}
	if contains(s.Names, arg) {
		return switchTo(arg, s)
	}
	matches := Match(arg, s.Names)
