func TestCtxPrefixTabEnterSwitchesAndLoadsWork(t *testing.T) {
	a := argRouter(t)
	ctxOpen(t, a, "ctx wo")
	press(t, a, "tab")
	posts := drive(t, a, press(t, a, "enter"))

