func TestCtxCurrentContextReloadsNothing(t *testing.T) {
	a := argRouter(t, "work", "web", "wip")
	view := a.currentView
	testutil.FastTimers(t, &components.FooterMsgDuration)
	ctxOpen(t, a, "ctx work")
