	}
	if a.previousContext != "" {
		t.Errorf("previousContext = %q, want it untouched", a.previousContext)
	}
}

func TestContextListPickingTheCurrentContextReloadsNothing(t *testing.T) {
	a := argRouter(t, "work", "web")
