	root := os.Getenv("HOME")
	listing := func() map[string]bool {
		out := map[string]bool{}
		_ = filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
			if err == nil && !d.IsDir() {
				out[p] = true
			}
			return nil
		})
		return out
	}
	before := listing()
	ctxRun(t, a, "ctx -")
	ctxRun(t, a, "ctx -")
	for p := range listing() {
		if !before[p] {
			t.Errorf("a switch wrote a new file: %s", p)
		}
	}
}

