func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		a.resize(msg.Width, msg.Height)
		return a, nil

	case tea.KeyMsg:
		return a.handleKeyMsg(msg)

	// ── Contexts and themes ──────────────────────────────────────────────
	case configuration.ConfigSavedMsg:
		return a.handleConfigSaved(msg)

	case contextNamesLoadedMsg:
		return a.handleContextNamesLoaded(msg)

	case MCPServerStartedMsg:
		return a.handleMCPServerStarted(msg)

	case mcpJobsRequestMsg:
		return a.handleMCPJobsRequest(msg)

	case mcpForwardsRequestMsg:
		return a.handleMCPForwardsRequest(msg)

	case mcpStartRequestMsg:
		return a.handleMCPStartRequest(msg)

	case mcpCancelRequestMsg:
		return a.handleMCPCancelRequest(msg)

	case jobs.RefusedMsg:
		return a.handleMCPRefused(msg)

	case ContextSwitchCompleteMsg:
		return a.handleContextSwitchComplete(msg)

	case ContextSwitchErrorMsg:
		log.Printf("ERROR: Context operation failed: %v", msg.Error)
		a.switchingTo = ""
		return a, nil

	case ContextListMsg:
		return a.handleContextList(msg)

	// ── GitLab authentication ────────────────────────────────────────────
	case auth.AuthResultMsg:
		return a.handleAuthResult(msg)

	case auth.LogoutCompleteMsg:
		return a.handleLogoutComplete(msg)
	} else {
		filename = fmt.Sprintf("config-%s.yaml", contextName)
	}

	return filepath.Join(configDir, filename), nil
}

// ValidateContextName validates the format of the context name
// Must be "default" or match ^[a-z0-9-]+$
func ValidateContextName(name string) error {
	if name == "default" {
		return nil
	}

	// Pattern: lowercase letters, digits, hyphens
	matched, err := regexp.MatchString("^[a-z0-9-]+$", name)
	if err != nil {
		return err
	}

	if !matched {
		return fmt.Errorf("invalid context name '%s': must contain only lowercase letters, numbers, and hyphens", name)
	}

	return nil
}

// Sentinel errors for context management; callers match them with errors.Is.
var (
	// ErrReservedContextName reports a name that cannot be used for a new context.
	ErrReservedContextName = errors.New("reserved context name")
	// ErrContextExists reports an attempt to create a context that already exists.
	ErrContextExists = errors.New("context already exists")
	// ErrContextNotFound reports a context with no config file.
	ErrContextNotFound = errors.New("context not found")
)

// reservedContextNames are rejected when creating a context (they stay
// loadable when a file already exists, so ValidateContextName accepts them).
var reservedContextNames = []string{"-", "new", "list"}

// ValidateNewContextName applies ValidateContextName, then refuses the
// reserved names. Use it only when creating a context.
func ValidateNewContextName(name string) error {
	if err := ValidateContextName(name); err != nil {
		return err
	}
	for _, r := range reservedContextNames {
		if name == r {
			return fmt.Errorf("%q is reserved — choose another name: %w", name, ErrReservedContextName)
		}
	}
	return nil
}

// CreateContext creates a new context with a default configuration
// Empty monitors, empty GitLab URL, other values default
func CreateContext(contextName string) error {
	if err := ValidateNewContextName(contextName); err != nil {
		return err
	}

	// Check whether it already exists
	exists, err := ContextExists(contextName)
	if err != nil {
		return err
	}
	if exists {
		return fmt.Errorf("context '%s' already exists: %w", contextName, ErrContextExists)
	}

	// Create config with defaults
	cfg := Default()

	// Clear monitors and forge for the new context
	cfg.Status.Components = []ComponentConfig{}
	cfg.Forge.URL = ""

	// Save
	return SaveContext(cfg, contextName)
}
